INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerktool immer eine grafische Oberfläche braucht?', 2, '[{"text": "Nein", "correct": true, "because": "CLI-Befehle wie `ip` funktionieren"}, {"text": "Ja", "correct": false, "because": "Terminal ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl zeigt mir die aktiven Netzwerkschnittstellen an?', 3, '[{"text": "`ip link show`", "correct": true, "because": "Listet Interfaces"}, {"text": "`ip route add`", "correct": false, "because": "Fügt Routen hinzu"}, {"text": "`ip addr del`", "correct": false, "because": "Löscht Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben kann ich mit einem Netzwerktool erledigen?', 5, '[{"text": "IP-Adressen zuweisen", "correct": true, "because": "Konfiguriert Schnittstellen"}, {"text": "Routing-Tabellen verwalten", "correct": true, "because": "Definiert Datenwege"}, {"text": "Interfaces aktivieren", "correct": true, "because": "Steuert Zustand"}, {"text": "Webseiten gestalten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) `ip addr show` zeigt IP-Adressen an. b) Es ersetzt `ifconfig` vollständig.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Moderne Alternative"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk mit einem Befehl konfiguriere?', 4, '[{"text": "Schnittstellen", "correct": false, "because": "Grundlage der Konfiguration"}, {"text": "IP-Adressen", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Netzwerktool nur Adressen anzeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Routing und mehr"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt eine neue IP-Adresse zu einer Schnittstelle hinzu?', 3, '[{"text": "`ip addr add`", "correct": true, "because": "Weist Adresse zu"}, {"text": "`ip link set`", "correct": false, "because": "Ändert Zustand"}, {"text": "`ip route show`", "correct": false, "because": "Zeigt Routen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modernes Netzwerktool?', 5, '[{"text": "Detaillierte Kontrolle", "correct": true, "because": "Feineinstellungen möglich"}, {"text": "Routing-Verwaltung", "correct": true, "because": "Flexibel einstellbar"}, {"text": "Schnittstellensteuerung", "correct": true, "because": "Aktiviert/deaktiviert"}, {"text": "Grafikdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) `ip route` Routen anzeigt und b) es nur für IPv4 ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch IPv6 unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Netzwerk mit einem Befehl zu verwalten?', 4, '[{"text": "Schnittstellenname", "correct": false, "because": "Identifiziert Interface"}, {"text": "IP-Adresse", "correct": false, "because": "Notwendig für Konfiguration"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Netzwerktool immer alle Routen an?', 2, '[{"text": "Ja", "correct": true, "because": "`ip route show` listet alles"}, {"text": "Nein", "correct": false, "because": "Standardverhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle helfen bei der Netzwerkverwaltung?', 4, '[{"text": "`ip addr`", "correct": true, "because": "Managed Adressen"}, {"text": "`ip route`", "correct": true, "because": "Managed Routen"}, {"text": "`ip design`", "correct": false, "because": "Nicht existent"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Netzwerktool nur für Profis ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Einsteiger nutzbar"}, {"text": "Ja", "correct": false, "because": "Breit einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Befehl zur Schnittstellensteuerung?', 3, '[{"text": "Netzwerk aktivieren", "correct": true, "because": "Schnittstellen hochfahren"}, {"text": "Webseiten gestalten", "correct": false, "because": "Irrelevant"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) `ip link set` aktiviert Interfaces. b) Es ist nur für IPv6.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch IPv4 unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt `ip route`?', 4, '[{"text": "Routing verwalten", "correct": true, "because": "Definiert Datenwege"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerktool auch IPv6-Adressen anzeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Unterstützt beide Versionen"}, {"text": "Nein", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Netzwerktool nützlich?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Viele Optionen"}, {"text": "Detaillierte Ausgabe", "correct": true, "because": "Zeigt Status"}, {"text": "Schnittstellensteuerung", "correct": true, "because": "Managed Interfaces"}, {"text": "Grafische Oberfläche", "correct": false, "because": "CLI-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt ein Netzwerktool `ifconfig` vollständig?', 3, '[{"text": "Ja", "correct": true, "because": "Moderne Alternative"}, {"text": "Nein", "correct": false, "because": "Vollständig ersetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Netzwerktool?', 4, '[{"text": "IP-Adresse einer Schnittstelle ändern", "correct": true, "because": "Typische Anwendung"}, {"text": "Webseite gestalten", "correct": false, "because": "Anderer Zweck"}, {"text": "Daten komprimieren", "correct": false, "because": "Nicht relevant"}]');
